import * as THREE from 'three/webgpu';
import { texture, uv, vec2, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-features-title';
  group.position.set(0, 3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const atlasRect = { x: 0, y: 0, w: 512, h: 320 };
  const atlasSize = 512;
  const aspect = atlasRect.w / atlasRect.h;

  const planeHeight = 0.62;
  const planeWidth = planeHeight * aspect;
  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  const grainMap = ctx.textureLoader.load(
    '/prism-assets/chrome/ceramic-grain.map.png'
  );
  grainMap.colorSpace = THREE.SRGBColorSpace;
  grainMap.wrapS = THREE.ClampToEdgeWrapping;
  grainMap.wrapT = THREE.ClampToEdgeWrapping;

  const uOffset = uniform(vec2(atlasRect.x / atlasSize, atlasRect.y / atlasSize));
  const uScale = uniform(vec2(atlasRect.w / atlasSize, atlasRect.h / atlasSize));

  const mappedUV = uv().mul(uScale).add(uOffset);
  const mapNode = texture(grainMap, mappedUV);

  const material = new THREE.MeshBasicNodeMaterial();
  material.map = grainMap;
  material.colorNode = mapNode;
  material.transparent = true;

  const backgroundPlane = new THREE.Mesh(geometry, material);
  backgroundPlane.name = 'features-title-bg';
  group.add(backgroundPlane);

  const inkColor = new THREE.Color(config?.colors?.ink ?? '#16161d');
  const paperColor = new THREE.Color(config?.colors?.paper ?? '#e8ecf2');

  const textMesh = ctx.fontAtlas.createText({
    text: 'Features',
    font: 'display',
    weight: 400,
    size: 0.34,
    color: paperColor,
    align: 'center',
    anchor: 'center',
  });
  textMesh.name = 'features-title-text';
  textMesh.position.set(0, 0, 0.01);
  group.add(textMesh);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (grainMap && typeof grainMap.dispose === 'function') {
      grainMap.dispose();
    }
    if (textMesh && typeof textMesh.geometry?.dispose === 'function') {
      textMesh.geometry.dispose();
    }
    if (textMesh && typeof textMesh.material?.dispose === 'function') {
      textMesh.material.dispose();
    }
  };

  return group;
}
